/**
 * Fake HP-UX 11.11 filesystem contents, seeded into the Lifo sandbox on first boot.
 * Generated from the original fixture; edit freely, it is just data. Modes are octal numbers.
 * Files with `bin: true` are stubs whose size is reported but whose content is a short marker.
 */

export interface TreeEntry {
  /** absolute path */ p: string;
  /** 'f' file or 'd' directory */ t: 'f' | 'd';
  /** unix mode bits */ m: number;
  /** owner */ o: string;
  /** group */ g: string;
  /** mtime as ls -l shows it */ mt: string;
  /** text content (files) */ c?: string;
  /** binary stub */ bin?: boolean;
  /** reported size for binary stubs */ size?: number;
}

